import RPi.GPIO as GPIO
import time
import logging
import threading
import queue
import atexit

# Configuration parameters
MOTION_SENSOR_1_PIN = 17
MOTION_SENSOR_2_PIN = 27
STATUS_LED_PIN = 22
illumination_threshold = 60
on_time = 60
off_delay = 300
sampling_period = 1.0  # seconds
motion_count_threshold = 2
debug_mode = True

# Global variables
motion_events_1 = 0
motion_events_2 = 0
ldr_value = 50  # Simulated LDR value
motion_sensor_1 = None
motion_sensor_2 = None
status_led_on = False
status_led_timer = None
status_led_event = threading.Event()
status_led_queue = queue.Queue()

# Logging setup
logging.basicConfig(level=logging.DEBUG if debug_mode else logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
GPIO.setmode(GPIO.BCM)
GPIO.setup(MOTION_SENSOR_1_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
GPIO.setup(MOTION_SENSOR_2_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
GPIO.setup(STATUS_LED_PIN, GPIO.OUT)

# Initialize motion sensors
motion_sensor_1 = MotionSensor(MOTION_SENSOR_1_PIN, motion_count_threshold, sampling_period)
motion_sensor_2 = MotionSensor(MOTION_SENSOR_2_PIN, motion_count_threshold, sampling_period)

# Initialize status LED
GPIO.output(STATUS_LED_PIN, GPIO.HIGH)

# Event queue for status updates
status_queue = queue.Queue()

# Function to handle status updates from the queue
def status_update_callback(channel):
    """Callback function to update the status LED based on events in the queue."""
    global status_led_on, status_led_timer, status_led_event, status_led_queue
    status_led_event.set()  # Signal that a status update is pending
    status_led_queue.put(True)
    status_led_timer = threading.Timer(on_time, turn_off_light)
    status_led_timer.start()

# Function to turn the light on
def turn_on_light():
    """Turns the light on and sets the status LED to HIGH."""
    global status_led_on, status_led_timer, status_led_event, status_led_queue
    status_led_event.set()  # Signal that a status update is pending
    status_led_queue.put(True)
    status_led_timer = threading.Timer(on_time, turn_off_light)
    status_led_timer.start()
    GPIO.output(STATUS_LED_PIN, GPIO.HIGH)
    logging.info("Light turned ON")

# Function to turn the light off
def turn_off_light():
    """Turns the light off and sets the status LED to LOW."""
    global status_led_on, status_led_timer, status_led_event, status_led_queue
    status_led_event.set()  # Signal that a status update is pending
    status_led_queue.put(True)
    status_led_timer = threading.Timer(off_delay, turn_on_light)
    status_led_timer.start()
    GPIO.output(STATUS_LED_PIN, GPIO.LOW)
    logging.info("Light turned OFF")

# Function to read LDR value (simulated)
def read_ldr():
    """Simulates reading the LDR value."""
    global ldr_value
    ldr_value = 50 + (time.time() % 10)  # Simulate LDR value fluctuating between 50 and 60
    logging.debug(f"Simulated LDR value: {ldr_value}")

# Function to check for motion events
def motion_detected_callback(channel):
    """Callback function to handle motion detection events."""
    global motion_events_1, motion_events_2, ldr_value, status_led_on, status_led_timer, status_led_event, status_led_queue
    if channel == motion_sensor_1.pin:
        motion_events_1 += 1
        if motion_events_1 >= motion_count_threshold:
            logging.info("Motion detected by sensor 1")
            status_queue.put(True)  # Signal to check status
            status_led_event.set()  # Signal to check status
            status_led_queue.put(True)
            status_led_timer = threading.Timer(on_time, turn_off_light)
            status_led_timer.start()
    elif channel == motion_sensor_2.pin:
        motion_events_2 += 1
        if motion_events_2 >= motion_count_threshold:
            logging.info("Motion detected by sensor 2")
            status_queue.put(True)  # Signal to check status
            status_led_event.set()  # Signal to check status
            status_led_queue.put(True)
            status_led_timer = threading.Timer(on_time, turn_off_light)
            status_led_timer.start()

# Function to check for motion events and control lighting
def lighting_control_callback(channel):
    """Callback function to control lighting based on motion and LDR readings."""
    global ldr_value, status_led_on, status_led_timer, status_led_event, status_led_queue
    if channel == motion_sensor_1.pin:
        if motion_events_1 > 0 and ldr_value > illumination_threshold:
            logging.info("Motion detected, LDR above threshold, turning light ON")
            turn_on_light()
    elif channel == motion_sensor_2.pin:
        if motion_events_2 > 0 and ldr_value > illumination_threshold:
            logging.info("Motion detected, LDR above threshold, turning light ON")
            turn_on_light()
    else:
        if status_led_on:
            logging.info("Motion detected, but status LED is ON, ignoring motion")
        else:
            logging.info("Motion detected, but status LED is OFF, turning light ON")
            turn_on_light()

# Class to encapsulate motion sensor functionality
class MotionSensor:
    """
    A class to encapsulate the functionality of a single PIR motion sensor.
    """
    def __init__(self, pin, motion_count_threshold, sampling_period):
        """
        Initializes the MotionSensor object.

        Args:
            pin (int): The GPIO pin the sensor is connected to.
            motion_count_threshold (int): The number of rising edge events required to trigger a motion detection.
            sampling_period (float): The time interval (in seconds) between sampling events.
        """
        self.pin = pin
        self.motion_count_threshold = motion_count_threshold
        self.sampling_period = sampling_period
        self.event_count = 0
        self.last_event_time = 0
        self.event_queue = queue.Queue()

    def register_callback(self, callback, bouncetime=200):
        """
        Registers a callback function to be called when a rising edge is detected.

        Args:
            callback (function): The callback function to be called.
            bouncetime (int): The debounce time in milliseconds.
        """
        GPIO.add_event_detect(self.pin, GPIO.RISING, callback=self._rising_edge_callback, bouncetime=bouncetime)

    def _rising_edge_callback(self, channel):
        """
        Internal callback function for rising edge detection.

        Args:
            channel (int): The GPIO pin that triggered the interrupt.
        """
        if time.time() - self.last_event_time > self.sampling_period:
            self.event_count += 1
            self.last_event_time = time.time()
            self.event_queue.put(self.event_count)
            self.event_count = 0

    def check_threshold(self):
        """
        Checks if the motion count exceeds the threshold.

        Returns:
            bool: True if the threshold is exceeded, False otherwise.
        """
        return self.event_count >= self.motion_count_threshold

    def reset_counter(self):
        """
        Resets the motion counter.
        """
        self.event_count = 0

    def get_motion_count(self):
        """
        Returns the current motion count.

        Returns:
            int: The current motion count.
        """
        return self.event_count

    def get_last_event_time(self):
        """
        Returns the timestamp of the last event.

        Returns:
            float: The timestamp of the last event.
        """
        return self.last_event_time

    def get_event_queue(self):
        """
        Returns the event queue.

        Returns:
            queue.Queue: The event queue.
        """
        return self.event_queue

