import time
import board
import busio
import digitalio
import adafruit_epd.epd
import adafruit_epd.il0373
import adafruit_bme280

# Configuration constants
UPDATE_INTERVAL_SECONDS = 60

def initialize_spi():
    """Initialize the SPI bus for communication with the BME280 sensor."""
    try:
        spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        return spi_bus
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return None

def initialize_bme280(spi_bus):
    """Initialize the BME280 sensor on the specified SPI bus."""
    try:
        chip_select = digitalio.DigitalInOut(board.GPIO7)
        sensor = adafruit_bme280.Adafruit_BME280_SPI(spi_bus, chip_select)
        return sensor
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return None

def initialize_epd():
    """Initialize the e-Paper display."""
    try:
        spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        epd = adafruit_epd.il0373.IL0373(128, 296, spi_bus, board.D5, board.D10, board.D11, board.D12, board.D13, board.D14, board.D15, board.D16, board.D17, board.D18, board.D19, board.D20, board.D21, board.D22, board.D23, board.D24, board.D25, board.D26, board.D27, board.D28, board.D29, board.D30, board.D31, digitalio.DigitalInOut(board.GPIO5), digitalio.DigitalInOut(board.GPIO6), digitalio.DigitalInOut(board.GPIO10))
        return epd
    except Exception as e:
        print(f"Error initializing e-Paper display: {e}")
        return None

def read_sensor_data(sensor):
    """Read temperature, humidity, and pressure from the BME280 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        return temperature, humidity, pressure
    except RuntimeError as e:
        print(f"BME280 read error: {e}")
        return None, None, None
    except ValueError as e:
        print(f"BME280 value error: {e}")
        return None, None, None

def update_display(epd, temperature, humidity, pressure):
    """Update the e-Paper display with the sensor readings."""
    try:
        epd.fill(adafruit_epd.WHITE)
        epd.text(f"Temp: {temperature:.1f} C", 0, 0, adafruit_epd.BLACK)
        epd.text(f"Hum: {humidity:.1f} %", 0, 20, adafruit_epd.BLACK)
        epd.text(f"Pres: {pressure:.1f} hPa", 0, 40, adafruit_epd.BLACK)
        epd.display()
    except Exception as e:
        print(f"Display update error: {e}")

def main():
    """Main function to read sensor data and update the e-Paper display."""
    spi_bus = initialize_spi()
    if spi_bus is None:
        return

    bme280_sensor = initialize_bme280(spi_bus)
    if bme280_sensor is None:
        return

    epd_display = initialize_epd()
    if epd_display is None:
        return

    try:
        while True:
            temperature, humidity, pressure = read_sensor_data(bme280_sensor)

            if temperature is not None and humidity is not None and pressure is not None:
                update_display(epd_display, temperature, humidity, pressure)

            time.sleep(UPDATE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Cleaning up resources.")

if __name__ == "__main__":
    main()

