import smbus
import time
import numpy as np
import matplotlib.pyplot as plt
import datetime
import os

# I2C address of the AMG8833 thermal camera sensor
AMG8833_ADDRESS = 0x69
# Pixel array dimensions of the thermal camera sensor
PIXEL_ARRAY_SIZE = 64
# Threshold temperature in Celsius
TEMPERATURE_THRESHOLD = 70.0
# Log file path
LOG_FILE_PATH = "/home/pi/thermal_logs/thermal_monitor_YYYYMMDD.log"
# Data log file path
DATA_LOG_FILE_PATH = "/home/pi/thermal_logs/thermal_data.csv"
# Image log directory path
IMAGE_LOG_DIR_PATH = "/home/pi/thermal_logs"

def verify_i2c_bus():
    """Verifies that the I2C bus is accessible on the Raspberry Pi."""
    try:
        bus = smbus.SMBus(1)  # Use I2C bus 1
        return True
    except Exception as e:
        log_message(f"I2C bus verification failed: {e}")
        return False

def verify_sensor_presence():
    """Verifies that the AMG8833 thermal camera sensor is present on the I2C bus."""
    try:
        bus = smbus.SMBus(1)
        bus.read_byte(AMG8833_ADDRESS)
        return True
    except Exception as e:
        log_message(f"AMG8833 sensor not found: {e}")
        return False

def initialize_thermal_camera():
    """Initializes the AMG8833 thermal camera sensor over I2C."""
    if not verify_i2c_bus() or not verify_sensor_presence():
        return None
    try:
        bus = smbus.SMBus(1)
        # Reset the sensor (see datasheet for details)
        bus.write_byte_data(AMG8833_ADDRESS, 0x00, 0x3F)
        return True
    except Exception as e:
        log_message(f"Thermal camera initialization failed: {e}")
        return None

def read_thermal_data():
    """Reads the 8x8 pixel data from the thermal camera sensor."""
    if not verify_sensor_presence():
        return None
    try:
        bus = smbus.SMBus(1)
        data = bus.read_i2c_block_data(AMG8833_ADDRESS, 0x80, PIXEL_ARRAY_SIZE * 2)
        # Convert to signed 16-bit integers
        pixel_data = np.array(data).reshape((8, 8))
        return pixel_data
    except Exception as e:
        log_message(f"Thermal data read failed: {e}")
        return None

def compute_average_temperature(pixel_data):
    """Computes the average temperature from the thermal camera data."""
    if pixel_data is None:
        return None
    try:
        average_temp = np.mean(pixel_data)
        return average_temp
    except Exception as e:
        log_message(f"Average temperature computation failed: {e}")
        return None

def generate_heatmap(pixel_data, filename):
    """Generates a heatmap image from the thermal camera data."""
    if pixel_data is None:
        return
    try:
        plt.imshow(pixel_data, cmap='jet', interpolation='nearest')
        plt.colorbar()
        plt.savefig(filename)
        plt.close()
    except Exception as e:
        log_message(f"Heatmap generation failed: {e}")

def log_data(timestamp, average_temp, filename):
    """Logs the thermal data to a CSV file."""
    if average_temp is None:
        return
    try:
        with open(DATA_LOG_FILE_PATH, "a") as logfile:
            logfile.write(f"{timestamp},{average_temp:.2f},{filename}\n")
    except Exception as e:
        log_message(f"Data logging failed: {e}")

def log_message(message):
    """Logs a message to the thermal monitor log file."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(LOG_FILE_PATH, "a") as logfile:
            logfile.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"CRITICAL ERROR: Could not write to log file: {e}")

def main():
    """Main function to run the thermal monitoring system."""
    if not initialize_thermal_camera():
        print("Thermal camera initialization failed. Exiting.")
        return

    try:
        while True:
            start_time = time.time()
            pixel_data = read_thermal_data()

            if pixel_data is not None:
                average_temp = compute_average_temperature(pixel_data)

                if average_temp is not None:
                    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                    image_filename = f"{IMAGE_LOG_DIR_PATH}/thermal_image_{timestamp}.png"
                    generate_heatmap(pixel_data, image_filename)
                    log_data(timestamp, average_temp, image_filename)

                    if average_temp > TEMPERATURE_THRESHOLD:
                        print(f"WARNING: High temperature detected: {average_temp:.2f} °C")
                        log_message(f"High temperature detected: {average_temp:.2f} °C")

                    time.sleep(0.1)  # Adjust sleep time as needed
                else:
                    log_message("Failed to compute average temperature.")
            else:
                log_message("Failed to read thermal data.")

            end_time = time.time()
            loop_time = end_time - start_time
            sleep_time = max(0, 1 - loop_time)  # Adjust sleep time to maintain 1 Hz
            time.sleep(sleep_time)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        log_message(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for smbus or matplotlib in this context,
        # but including a placeholder for potential future resource management.
        print("Program finished.")

if __name__ == "__main__":
    main()

