# Bluetooth serial transmitter for Raspberry Pi using the rfcomm interface
# Sends data over a Bluetooth serial link to a remote device
import os
import subprocess
import logging

# Configure logging for the Bluetooth transmitter
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400

def open_bluetooth_port():
    """Open the Bluetooth serial port on the Raspberry Pi."""
    # Use the rfcomm tool to bring the Bluetooth device online
    try:
        result = subprocess.run(
            ["sudo", "rfcomm", "port", "open", BLUETOOTH_DEVICE],
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            raise RuntimeError("Failed to open Bluetooth device")
        logging.info("Bluetooth port %s opened", BLUETOOTH_DEVICE)
        return result.returncode == 0
    except FileNotFoundError:
        raise RuntimeError("rfcomm tool not found")
    except Exception as error:
        logging.error("Bluetooth port open failed: %s", error)
        raise

def send_data(port_open, data_string):
    """Send a string over the open Bluetooth serial port."""
    # Write the data string to the Bluetooth device
    if not port_open:
        raise RuntimeError("Bluetooth port not open")
    encoded_data = data_string + "\x01"
    try:
        result = subprocess.run(
            ["echo", encoded_data],
            capture_output=True,
            text=True,
            check=True,
    )
    if result.returncode != 0:
        raise RuntimeError("Failed to write to Bluetooth device")
    logging.info("Sent: %s", data_string)
    return True

def main():
    """Open the Bluetooth port and transmit data until interrupted."""
    try:
        if not open_bluetooth_port():
            return
        with subprocess.Popen(
            ["screen", "-S", "bluetooth_link", "-dev", BLUETOOTH_DEVICE, "-L"],
            text=True,
        ) as link_process:
            while True:
                # Read a line from the user and send it over Bluetooth
                user_input = input("Enter data (or 'q' to quit): ")
                if user_input.lower() == "q":
                    break
                if send_data(True, user_input):
                    pass
                else:
                    break
    except RuntimeError as error:
        logging.error("Error: %s", error)
    except KeyboardInterrupt:
        logging.info("Stopped by user")
    finally:
        # Always close the Bluetooth port on exit
        if 'link_process' in locals() and link_process.poll() is not None:
            link_process.terminate()
        if 'link_process' in locals() and link_process.wait() != 0:
            link_process.kill()

if __name__ == "__main__":
    main()

