import time
import numpy as np
import cv2
import RPi.GPIO as GPIO
from picamera import PiCamera
from termios import *
import tty
import logging

# Logging setup for the object tracking system
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Constants for the object tracking configuration
MIN_CONTOUR_AREA = 500
FONT = cv2.FONT_HERSHEY_SIMPLEX
FONT_SCALE = 0.5
FONT_COLOR = (255, 255, 255)  # White
LINE_THICKNESS = 2
HSV_LOWER_BLUE = np.array([100, 100, 100])
HSV_UPPER_BLUE = np.array([130, 255, 255])

# GPIO configuration for the UART module
UART_PORT = 0
UART_BAUDRATE = 9600
UART_TIMEOUT = 1


def configure_camera():
    """Initialize and configure the Raspberry Pi camera."""
    camera = PiCamera()
    camera.resolution = (640, 480)
    camera.framerate = 32
    time.sleep(2)
    return camera


def setup_uart():
    """Initialize and configure the UART serial port."""
    try:
        uart = serial.Serial(
            port=UART_PORT,
            baudrate=UART_BAUDRATE,
            bytesize=8,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=UART_TIMEOUT,
        )
        return uart
    except serial.SerialException as e:
        logging.error(f"UART setup failed: {e}")
        return None


def send_command(uart, message):
    """Send a command over the UART with error handling."""
    try:
        uart.write(message.encode("utf-8"))
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_numeric_command(uart, number):
    """Send a numeric command over the UART with error handling."""
    command = f"0x{number:02X}\n"
    if send_command(uart, command):
        logging.info(f"UART sent command: {command.strip()}")
    else:
        logging.error(f"UART send failed for command: {command.strip()}")


def send_character(uart, char):
    """Send a character over the UART with error handling."""
    try:
        uart.write(char.encode("utf-8"))
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_character_async(uart, char):
    """Non-blocking UART send function."""
    try:
        uart.write(char.encode("utf-8"))
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_byte(uart, byte):
    """Send a byte over the UART with error handling."""
    try:
        uart.write(byte.to_bytes(1, "little", signed=False))
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_byte_async(uart, byte):
    """Non-blocking UART byte send function."""
    try:
        uart.write(byte.to_bytes(1, "little", signed=False))
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_frame(uart, frame_data):
    """Send a frame over the UART with error handling."""
    try:
        uart.write(frame_data)
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def send_frame_async(uart, frame_data):
    """Non-blocking UART frame send function."""
    try:
        uart.write(frame_data)
        return True
    except serial.SerialException as e:
        logging.error(f"UART send failed: {e}")
        return False


def initialize_camera(camera):
    """Initialize the camera and return the frame."""
    try:
        camera.start_preview()
        time.sleep(2)
        return True


def capture_frame(camera):
    """Capture a frame from the camera and return it as a NumPy array."""
    try:
        return camera.capture_array()
    except Exception as e:
        logging.error(f"Camera capture failed: {e}")
        return None


def process_frame(frame, camera):
    """Process the frame to detect and track a blue object."""
    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2HSV)
    mask = cv2.inRange(hsv_frame, HSV_LOWER_BLUE, HSV_UPPER_BLUE)
    contours, _ = cv2.findContours(
        mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
    )
    largest_contour = None
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = contour

    if largest_contour is not None and largest_area > MIN_CONTOUR_AREA:
        x, y, w, h = cv2.boundingRect(largest_contour)
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
        object_position = "bottom_right"
        if w > h > 50:
            object_position = "top_right"
        elif h > w > 50:
            object_position = "bottom_left"
        elif h < w < 50:
            object_position = "top_left"
        else:
            object_position = "centre"

        send_numeric_command(
            uart,
            1 if object_position == "centre" else int(object_position[0], 16),
        )
        logging.info(
            f"Object detected {object_position}, position: {object_position}, area: {largest_area}"
        )
    return frame


def main():
    """Main function to run the object tracking system."""
    global uart
    uart = setup_uart()

    if uart is None:
        logging.error("UART setup failed. Exiting.")
        return

    try:
        camera = configure_camera()
        if not initialize_camera(camera):
            logging.error("Camera initialization failed. Exiting.")
            return

        if not camera.is_zoomed():
            camera.start_recording("/dev/null", format="h264", framerate=32)

        logging.info("Object tracking started. Press ESC to exit.")

        while True:
            frame = capture_frame(camera)
            if frame is None:
                continue

            processed_frame = process_frame(frame, camera)

            if uart:
                try:
                    send_frame_async(uart, processed_frame.tobytes())
                except Exception as e:
                    logging.error(f"UART send failed: {e}")

            key = cv2.waitKey(1) & 0xFF
            if key == 27:
                break

            if key == ord("s"):
                send_command(uart, "s")
                logging.info("HSV range sampling requested.")
            elif key == ord("o"):
                send_command(uart, "o")
                logging.info("Color range turned OFF.")
            elif key == ord("c"):
                send_command(uart, "c")
                logging.info("Color range sampling requested.")

    except KeyboardInterrupt:
        logging.info("Object tracking interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Releasing resources.")
        if 'camera' in locals():
            camera.stop_preview()
            camera.stop_recording()
        cv2.destroyAllWindows()
        if uart:
            try:
                send_command(uart, "0x01")  # Clear the line
                tty.setcbreak(stdscr._rkb)
                os._exit(0)
            except Exception as e:
                logging.error(f"Error during UART cleanup: {e}")
        GPIO.cleanup()


if __name__ == "__main__":
    main()

