import os
import time
import datetime
import logging
import signal
import sys
import json
import urllib.request
import shutil
import subprocess

import cv2
import numpy as np
import psutil
from time import sleep

# Set up basic logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for image processing
IMAGE_SIZE = 224
MEAN = [0.485, 0.456, 0.406]
STD = [0.229, 0.224, 0.225]
FLIP = True

class InferenceRunner:
    """Handles image transformation and model inference."""

    def __init__(self, model_path, label_path, use_hor: bool = False):
        self.model_path = model_path
        self.label_path = label_path
        self.use_hor = use_hor
        self.net = None
        self.labels = self._load_labels()
        self.load_model()

    def load_labels(self):
        """Loads the labels file."""
        try:
            with open(self.label_path, 'r', encoding='utf-8') as f:
                return [line.strip() for line in f]
        except FileNotFoundError:
            logger.error(f"Labels file not found: {self.label_path}")
            raise
        except Exception as e:
            logger.error(f"Error loading labels: {e}")
            raise

    def load_model(self):
        """Loads the TensorFlow model."""
        try:
            self.net = cv2.dnn.readNet(self.model_path, self.use_hor)
        except Exception as e:
            logger.error(f"Error loading model: {e}")
            raise

    def transform_image(self, image_path: str):
        """Transforms an image for inference."""
        try:
            image = cv2.imread(image_path)
            if image is None:
                raise FileNotFoundError(f"Image not found: {image_path}")

            height, width = image.shape[:2]

