import time
import logging
import board
import busio
import adafruit_bmp280
import RPi.GPIO as GPIO

# Configure logging to a file for error tracking
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins for the indicator LEDs
LED_PINS = [17, 27, 22]

# Define pressure thresholds for the LEDs
PRESSURE_THRESHOLDS = [990.0, 1010.0]

def initialize_sensor():
    """Initializes the BMP280 sensor over the I2C bus."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        bmp280 = adafruit_bmp280.Adafruit_BMP280_I2C(i2c)
        time.sleep(1)  # Allow sensor to stabilize
        return bmp280
    except Exception as e:
        logging.error(f"Sensor initialization failed: {e}")
        return None

def initialize_leds():
    """Initializes the GPIO pins for the indicator LEDs."""
    GPIO.setmode(GPIO.BCM)
    for pin in LED_PINS:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)

def update_leds(pressure):
    """Updates the LEDs based on the measured pressure."""
    try:
        for i, pin in enumerate(LED_PINS):
            if pressure < PRESSURE_THRESHOLDS[i]:
                GPIO.output(pin, GPIO.HIGH)
            else:
                GPIO.output(pin, GPIO.LOW)
    except Exception as e:
        logging.error(f"LED update failed: {e}")

def main():
    """Main function to read pressure and control LEDs."""
    sensor = initialize_sensor()
    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return

    initialize_leds()

    try:
        while True:
            try:
                pressure = sensor.pressure
                print(f"Pressure: {pressure:.2f} hPa")
                update_leds(pressure)
            except Exception as e:
                logging.error(f"Error reading pressure or updating LEDs: {e}")
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO pins on exit
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

