import time
import os
import sys
from datetime import datetime

# Define a class to wrap the temperature reading
class CPUTemperature:
    """Reads the CPU temperature from the Raspberry Pi thermal zone file."""

    def __init__(self, thermal_zone_path="/sys/class/thermal/thermal_zone0/temp"):
        """Create the CPUTemperature object and open the temperature file."""
        self.thermal_zone_path = thermal_zone_path
        self.file_handle = None
        self.open_file()

    def open_file(self):
        """Open and validate the thermal zone temperature file."""
        try:
            self.file_handle = open(self.thermal_zone_path, "r")
            self.file_handle.seek(0, os.SEEK_END)  # Seek to the end of the file
            self.file_handle.readline()  # Skip the empty header line
        except FileNotFoundError as open_error:
            print(f"Could not open thermal zone file: {open_error}")
            raise  # Re-raise so the program stops if the file is missing
        except Exception as open_error:
            print(f"Error opening thermal zone file: {open_error}")
            raise

    def read_temperature(self):
        """Read and return the CPU temperature in Celsius."""
        if self.file_handle is None:
            return None
        try:
            temperature_value = float(self.file_handle.readline().strip()) / 1000.0
            return temperature_value
        except ValueError as read_error:
            print(f"Error reading temperature: {read_error}")
            return None
        except Exception as read_error:
            print(f"Error reading temperature: {read_error}")
            return None

    def close(self):
        """Close the temperature file."""
        if self.file_handle is not None:
            self.file_handle.close()

def print_temperature(temperature_value):
    """Print the CPU temperature with a timestamp."""
    print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}, CPU Temperature: {temperature_value:.2f} °C")

def main():
    """Main function to read and print the CPU temperature repeatedly."""
    try:
        # Create the CPUTemperature object
        cpu_temp = CPUTemperature()
        # Read and print the temperature a few times
        for _ in range(5):
            temperature_value = cpu_temp.read_temperature()
            if temperature_value is not None:
                print_temperature(temperature_value)
            time.sleep(1)
    except Exception as main_error:
        print(f"Main loop error: {main_error}")
    finally:
        # Always close the temperature file when finished
        if 'cpu_temp' in locals():
            cpu_temp.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

