import time
import smbus2 as smbus
import logging
from typing import Tuple, List

# Configure logging for the DHT20 driver
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# I2C bus and device constants for the Raspberry Pi
I2C_BUS_NUMBER = 1
DHT20_I2C_ADDRESS = 0x76
MEASUREMENT_RETRY_DELAY_SECONDS = 0.5
MEASUREMENT_MAX_RETRIES = 5
MEASUREMENT_RETRY_DELAY_MULTIPLIER = 0.1
MEASUREMENT_MAX_RETRY_DELAY = 0.8
DATA_REGISTER_BASE = 0x71
DATA_START_BYTE = 0x00
DATA_END_BYTE = 0x0A
MEASUREMENT_RESULT_START_BYTE = 0xFA
MEASUREMENT_RESULT_BYTE_7 = 0x07
MEASUREMENT_RESULT_BYTE_6 = 0x06
MEASUREMENT_RESULT_BYTE_5 = 0x05
MEASUREMENT_RESULT_BYTE_4 = 0x04
MEASUREMENT_RESULT_BYTE_3 = 0x03
MEASUREMENT_RESULT_BYTE_2 = 0x02
MEASUREMENT_RESULT_BYTE_1 = 0x01
MEASUREMENT_RESULT_BYTE_0 = 0x00
CRC_LENGTH = 4

class DHT20Error(Exception):
    """Base class for DHT20 sensor errors."""
    pass


class InvalidMeasurementError(DHT20Error):
    """Raised when a measurement cannot be taken."""
    pass


class I2CCommunicationError(DHT20Error):
    """Raised when an I2C communication error occurs."""
    pass


class DHT20Driver:
    """Driver class for the Aosong DHT20 temperature and humidity sensor."""

    def __init__(self, bus_number: int = I2C_BUS_NUMBER, device_address: int = DHT20_I2C_ADDRESS):
        """Initialize the I2C bus and device address."""
        self.bus = smbus.SMBus(bus_number)
        self.device_address = device_address
        self._last_measurement_time = 0.0

    def begin(self) -> bool:
        """Initialize the sensor by powering it on and waiting for it to stabilize."""
        try:
            # Power on the sensor and wait for it to stabilize
            self.bus.write_byte_data(self.device_address, 0x0D, 0x01)
            time.sleep(MEASUREMENT_RETRY_DELAY_SECONDS)
            if self.bus.read_byte_data(self.device_address, 0x0D) != 0x01:
                raise I2CCommunicationError(
                    f"DHT20: Failed to power on. Expected 0x01, got 0x{self.bus.read_byte_data(self.device_address, 0x0D):02X}"
                )
            time.sleep(1)
            self._last_measurement_time = time.time()
            logging.info("DHT20: Initialisation successful.")
            return True
        except OSError as e:
            logging.error(f"DHT20: Failed to initialise: {e}")
            return False

    def get_temperature_and_humidity(self) -> Tuple[float, float]:
        """Perform a measurement and return the temperature and humidity."""
        # Check if enough time has passed since the last measurement
        if (time.time() - self._last_measurement_time) < 2.0:
            self._last_measurement_time = time.time()
            return self._cached_measurement_result()

        # Retry mechanism for measurement failures
        for attempt in range(MEASUREMENT_MAX_RETRIES):
            try:
                self._perform_measurement()
                return self._extract_measurement_values()
            except InvalidMeasurementError:
                logging.warning(f"DHT20: Attempt {attempt + 1} failed. Retrying...")
                time.sleep(MEASUREMENT_RETRY_DELAY_MULTIPLIER * (MEASUREMENT_MAX_RETRY_DELAY - (time.time() - MEASUREMENT_RETRY_DELAY_SECONDS)))
            except Exception as e:
                logging.error(f"DHT20: Unexpected error during measurement: {e}")
                return self._cached_measurement_result()  # Return cached values on unexpected errors

        # Handle the case where all retries fail
        raise InvalidMeasurementError(
            "DHT20: Failed after multiple retries."
        )

    def _perform_measurement(self) -> None:
        """Perform a single measurement and store the data."""
        # Read the measurement result
        data = self.bus.read_i2c_block_data(self.device_address, DATA_START_BYTE, 7)
        if data[CRC_LENGTH] != self._calculate_crc(data[:-1]):
            raise InvalidMeasurementError(
                "DHT20: CRC check failed."
            )
        self._extract_measurement_values_from_data(data)

    def _extract_measurement_values_from_data(self, data: List[int]) -> Tuple[float, float]:
        """Extract temperature and humidity values from the raw data."""
        temperature_raw = ((data[MEASUREMENT_RESULT_BYTE_1] << 16) |
                           (data[MEASUREMENT_RESULT_BYTE_2] << 8) | data[MEASUREMENT_RESULT_BYTE_3]) / 5242.88 - 50
        humidity_raw = ((data[MEASUREMENT_RESULT_BYTE_4] << 8) | data[MEASUREMENT_RESULT_BYTE_5]) / 0x100000 * 100

        # Validate the readings
        if not (0x10 <= temperature_raw <= 0x30 and 0x00 <= humidity_raw <= 0x7F):
            raise InvalidMeasurementError(
                "DHT20: Invalid measurement data."
            )

    def _calculate_crc(self, data: List[int]) -> int:
        """Calculate the CRC-8 checksum."""
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc = crc << 1
        return crc & 0xFF

    def _write_data(self, register: int, data: List[int]) -> None:
        """Write data to a register."""
        try:
            self.bus.write_i2c_block_data(self.device_address, register, data)
        except OSError as e:
            raise I2CCommunicationError(f"DHT20: I2C write error: {e}")

    def _read_data(self, register: int, length: int) -> List[int]:
        """Read data from a register."""
        try:
            return self.bus.read_i2c_block_data(self.device_address, register, length)
        except OSError as e:
            raise I2CCommunicationError(f"DHT20: I2C read error: {e}")

    def _cached_measurement_result(self) -> Tuple[float, float]:
        """Return cached measurement results."""
        # Check if cached values are still valid
        if (time.time() - self._last_measurement_time) < 2.0:
            return self._cached_measurement_result_value

    def _cached_measurement_result_value(self) -> Tuple[float, float]:
        """Compute and cache the measurement result."""
        try:
            # Perform the measurement
            self._perform_measurement()

            # Extract and cache the values
