import serial
import time
import logging
import RPi.GPIO as GPIO
import signal
import sys

# Logging configuration for the hydroponics alert system
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

# GPIO pin for the alert LED
ALERT_LED_PIN = 17
# UART port and baud rate for the sensor
UART_PORT = "/dev/ttyACM0"
UART_BAUD = 115200
# Temperature and humidity thresholds
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
# Log file path
LOG_FILE = "/home/pi/sensor_log.txt"


def configure_gpio():
    """Configure the alert LED pin as an output."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_LED_PIN, GPIO.OUT)


def cleanup_gpio(signal=None, frame=None):
    """Clean up GPIO resources before exiting."""
    logging.info("Cleaning up GPIO")
    GPIO.cleanup()


def read_sensor_data(serial_port):
    """Read a line from the serial port and decode it."""
    try:
        line = serial_port.readline().decode("utf-8", errors="ignore").strip()
        return line
    except Exception as read_error:
        logging.error("Sensor read error: %s", read_error)
        return None


def parse_sensor_data(sensor_line):
    """Parse a comma-separated temperature/humidity line into floats."""
    try:
        parts = sensor_line.split(",")
        if len(parts) == 2:
            return float(parts[0]), float(parts[1])
        else:
            logging.warning("Invalid sensor data format: %s", sensor_line)
            return None, None
    except ValueError as parse_error:
        logging.error("Sensor parse error: %s", parse_error)
        return None, None


def trigger_alert(alert_led_pin, duration_seconds):
    """Turn the alert LED on for a specified duration."""
    try:
        GPIO.output(alert_led_pin, GPIO.HIGH)
        time.sleep(duration_seconds)
        GPIO.output(alert_led_pin, GPIO.LOW)
    except Exception as alert_error:
        logging.error("Alert trigger error: %s", alert_error)


def log_reading(log_file, timestamp, temperature, humidity):
    """Append a timestamped reading to the log file."""
    try:
        with open(log_file, "a") as logfile:
            logfile.write(
                f"{timestamp}, {temperature:.1f}C, {humidity:.1f}%\n"
            )
    except Exception as log_error:
        logging.error("Log write error: %s", log_error)


def main_loop(serial_port, alert_led_pin, log_file):
    """Continuously read sensor data and trigger alerts."""
    try:
        while True:
            sensor_line = read_sensor_data(serial_port)
            if sensor_line:
                temperature, humidity = parse_sensor_data(sensor_line)
                if temperature is not None and humidity is not None:
                    logging.info("Temperature: %.1fC, Humidity: %.1f%%", temperature, humidity)
                    log_reading(log_file, time.strftime("%Y-%m-%dT%H:%M:%S"), temperature, humidity)
                    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                        trigger_alert(alert_led_pin, 5)
            time.sleep(1)
    except Exception as main_loop_error:
        logging.error("Main loop error: %s", main_loop_error)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    configure_gpio()
    signal.signal(signal.SIGTERM, cleanup_gpio)
    try:
        with serial.Serial(UART_PORT, UART_BAUD, timeout=1) as ser:
            main_loop(ser, ALERT_LED_PIN, LOG_FILE)
    except serial.SerialException as serial_error:
        logging.error("Serial port error: %s", serial_error)
    except Exception as main_exception:
        logging.error("Fatal error: %s", main_exception)
    sys.exit(0)

