import RPi.GPIO as GPIO
import time
import requests
from requests.auth import HTTPBasicAuth

# GPIO pin for the digital sensor
SENSOR_PIN = 4
# Server URL for the sensor data
SERVER_URL = "http://localhost:5000/sensor"
# Basic authentication credentials
USERNAME = "alice"
PASSWORD = "secret"


def setup_sensor():
    """Set up the GPIO pin for the digital sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)


def read_sensor_value():
    """Read the current value from the digital sensor."""
    return GPIO.input(SENSOR_PIN)


def post_sensor_data(value):
    """Send sensor data to the server."""
    payload = {"sensor": "digital_input", "value": int(value)}
    try:
        response = requests.post(
            SERVER_URL,
            json=payload,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
        )
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")


if __name__ == "__main__":
    try:
        setup_sensor()
        while True:
            sensor_value = read_sensor_value()
            if sensor_value == 1:
                post_sensor_data(1)
            else:
                post_sensor_data(0)
            time.sleep(5)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        GPIO.cleanup()

