import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO
import signal

# GPIO pin for the LED
LED_GPIO_PIN = 18
# I2C bus number on the Raspberry Pi
I2C_BUS_NUMBER = 1
# Integration time for the light sensor
INTEGRATION_TIME_MS = 402
# PWM frequency for the LED
PWM_FREQUENCY_HZ = 1000


def initialize_i2c():
    """Set up the I2C bus for the TSL2561 light sensor."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as setup_error:
        print("I2C setup failed:", setup_error)
        return None


def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor with a given integration time."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus, gain=adafruit_tsl2561.GAIN_1X)
    except Exception as setup_error:
        print("Light sensor setup failed:", setup_error)
        return None


def initialize_pwm(led_pin, frequency):
    """Create and start a PWM instance for the LED brightness control."""
    pwm_instance = GPIO.PWM(led_pin, frequency)
    pwm_instance.start(0)
    return pwm_instance


def read_light_level(light_sensor):
    """Read the ambient light level in lux from the TSL2561 sensor."""
    try:
        return light_sensor.lux
    except Exception as read_error:
        print("Light read failed:", read_error)
        return None


def map_light_to_brightness(light_level):
    """Convert a light level in lux to a PWM duty cycle percentage."""
    if light_level is None:
        return 0.0
    return light_level / 10.0


def update_led_brightness(pwm_instance, brightness_percent):
    """Set the LED brightness using hardware PWM duty cycle."""
    try:
        pwm_instance.ChangeDutyCycle(brightness_percent)
    except Exception as set_error:
        print("LED brightness set failed:", set_error)


def signal_handler(sig, frame):
    """Handle signals like SIGINT (Ctrl+C) to stop the program gracefully."""
    print("Exiting gracefully...")
    try:
        pwm_instance.stop()
    except Exception as stop_error:
        print("PWM stop failed:", stop_error)
    GPIO.cleanup()


def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        return

    pwm_instance = initialize_pwm(LED_GPIO_PIN, PWM_FREQUENCY_HZ)

    # Register the signal handler
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                brightness_percent = map_light_to_brightness(light_level)
                update_led_brightness(pwm_instance, brightness_percent)
                print("Light: {:.2f} lux, Brightness: {:.2f}%".format(light_level, brightness_percent))
            time.sleep(1)
    except Exception as main_error:
        print("Main loop error:", main_error)
    finally:
        # Ensure resources are released on exit
        try:
            pwm_instance.stop()
            GPIO.cleanup()
        except Exception as cleanup_error:
            print("Final cleanup failed:", cleanup_error)


if __name__ == "__main__":
    main()

