#!/usr/bin/env python3

"""
Monitors Raspberry Pi GPIO pins and logs state changes.

Detects the board revision and configures GPIO numbering mode.
Subsequently sets up debounced input pins for each listed pin number.
Records each state change with a timestamp using an in-memory log.
"""

import RPi_RealTime as GPIO
import time
import signal
import sys
import functools
from typing import List, Callable, Optional

# Constants
GPIO_MAX_WAIT = 1000  # milliseconds
DEFAULT_DEBOUNCE_MS = 200
LOG_FILE = "gpio_monitor.log"


def log_message(message: str) -> None:
    """Appends a timestamped message to the log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(LOG_FILE, "a") as logfile:
            logfile.write(f"{timestamp} {message}\n")
    except Exception as e:
        print(f"Error writing to log: {e}")


def get_gpio_num(revision: int) -> int:
    """Returns the GPIO numbering scheme based on the board revision."""
    return 17 if revision == 1 else 26


def auto_detect_model() -> int:
    """Autodetects the Raspberry Pi model by reading the board revision."""
    try:
        with open("/proc/cpuinfo", "r") as cpuinfo:
            for line in cpuinfo:
                if line.startswith("Revision"):
                    return int(line.rstrip()[-4:])
    except Exception:
        return 0  # Default to unknown model


def setup_gpio(gpio_module: GPIO.RealIO, gpio_num: int, debounce_ms: int) -> None:
    """Sets up a GPIO pin with debouncing and a callback function."""
    pin_number = gpio_module.pin(gpio_num, gpio_module.IN, initial_value=0)
    gpio_module.callback = functools.partial(
        lambda pin, old_state, new_state: log_message(
            f"Pin {pin}: {'HIGH' if new_state else 'LOW'} (Debounce: {debounce_ms}ms)"
        ),
        rev=3,
    )
    gpio_module.debounce(debounce_ms)


def run_monitor(gpio_module: GPIO.RealIO, gpio_pins: List[int], debounce_ms: int) -> None:
    """Monitors the configured GPIO pins for state changes."""
    log_message("Monitoring...")
    last_states = {pin: 0 for pin in gpio_pins}
    signal.signal(signal.SIGINT, lambda *args: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))

    while True:
        for pin in gpio_pins:
            current_state = gpio_module.input(pin)
            if current_state != last_states[pin]:
                log_message(f"Pin {pin} state changed to {'HIGH' if current_state else 'LOW'}")
                last_states[pin] = current_state
        time.sleep(0.1)


def main() -> None:
    """Main function to orchestrate the GPIO monitoring."""
    model = auto_detect_model()
    log_message("Detected model: " + (GPIO.RPI_REVISION_CODES[model] if model >= 0 else "unknown"))

    gpio_num = get_gpio_num(GPIO.RPI_REVISION_CODES[model])
    debounce_time = DEFAULT_DEBOUNCE_MS if debounce_ms is None else debounce_ms

    gpio_module = GPIO.RealIO(gpio_num, board=True, revision=GPIO.RPI_REVISION_CODES[model])
    if debounce_ms is not None:
        gpio_module.debounce(debounce_time)

    gpio_pins = [gpio_module.pin(pin, gpio_module.IN, initial_value=0) for pin in [gpio_module.pin(gpio_num, gpio_num, initial_value=0)]]

    run_monitor(gpio_module, gpio_pins, debounce_time)


if __name__ == "__main__":
    main()

