DEBOUNCE_DELAY = 0.1  # seconds

# Setup logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def read_sensor(pin):
    """Reads the state of a PIR sensor with debouncing."""
    return GPIO.input(pin) == 0  # Active low

def activate_actuator(actuator_name):
    """Activates a simulated actuator."""
    logging.info(f"Activating actuator: {actuator_name}")

def handle_intrusion(sensor_num, pin, actuators):
    """Handles an intrusion event."""
    logging.warning(f"Intrusion Detected by Sensor {sensor_num} at Pin {pin}")
    activate_actuator("Intrusion Detected")
    for actuator in actuators:
        activate_actuator(actuator)

def main():
    """Main function to monitor sensors and handle intrusions."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SENSOR_1_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(SENSOR_2_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        logging.info("Art installation started")

        while True:
            # Check for intrusion
            if read_sensor(SENSOR_1_PIN) and read_sensor(SENSOR_2_PIN):
                start_time = time.time()
                while time.time() - start_time < 0.5:
                    if not read_sensor(SENSOR_1_PIN) or not read_sensor(SENSOR_2_PIN):
                        break
                if time.time() - start_time >= 0.5:
                    handle_intrusion(1, SENSOR_1_PIN, ACTUATORS)
            elif read_sensor(SENSOR_1_PIN):
                handle_intrusion(1, SENSOR_1_PIN, ACTUATORS)
            elif read_sensor(SENSOR_2_PIN):
                handle_intrusion(2, SENSOR_2_PIN, ACTUATORS)

            time.sleep(DEBOUNCE_DELAY)

    except RuntimeError as e:
        logging.error(f"RuntimeError: {e}")
    except KeyboardInterrupt:
        logging.info("Art installation stopped by user")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed")

if __name__ == "__main__":
    main()

