    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_accelerometer(i2c_bus):
    """Initialize the LIS3DH accelerometer."""
    try:
        return adafruit_lis3dh.LIS3DH_I2C(i2c_bus)
    except Exception as e:
        print(f"Error initializing accelerometer: {e}")
        return None

def initialize_gpio():
    """Initialize GPIO pins for LED and buzzer."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT)
    GPIO.setup(BUZZER_PIN, GPIO.OUT)

def read_acceleration(accelerometer):
    """Read acceleration values from the accelerometer."""
    try:
        x, y, z = accelerometer.acceleration
        return x, y, z
    except Exception as e:
        print(f"Error reading acceleration: {e}")
        return None, None, None

def combine_axis(x, y, z):
    """Combine axis values into a single signed 16-bit integer."""
    if x is None or y is None or z is None:
        return None
    return (x >> 4) * 16 + (y >> 4) * 16 + (z >> 4) * 16

def check_threshold(combined_value, x_threshold, y_threshold):
    """Check if the combined acceleration value exceeds the thresholds."""
    if combined_value is None:
        return False
    return combined_value > x_threshold or combined_value > y_threshold

def activate_led(pin):
    """Turn on the LED."""
    GPIO.output(pin, GPIO.HIGH)

def deactivate_led(pin):
    """Turn off the LED."""
    GPIO.output(pin, GPIO.LOW)

