#!/usr/bin/env python3

"""
Controls a garage door using a Raspberry Pi and an Automation HAT with a relay.
A magnetic reed switch indicates door state, switching the relay on close and off.
"""

import time
import logging
from automation import relay
from automation.driver import HAT

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Define GPIO pin for the reed switch (BCM numbering)
REED_SWITCH_PIN = 1
# Define GPIO pin for the relay control (BCM numbering)
RELAY_PIN = 2

class GarageDoor:
    """Controls a garage door using a relay on an Automation HAT."""

    def __init__(self, reed_pin=REED_SWITCH_PIN, relay_pin=RELAY_PIN):
        """Initializes the GarageDoor object."""
        self.reed_pin = reed_pin
        self.relay_pin = relay_pin
        self.relay_device = None
        self.is_door_open = False
        self.setup_automation_hat()

    def setup_automation_hat(self):
        """Checks if the Automation HAT is connected and initializes the relay."""
        try:
            hat = HAT()
            hat.set_74HC595_pins(0, 13)
            self.relay_device = hat.get_relay(self.relay_pin)
            self.relay_device.on()  # Start with the relay off
            logging.info("Automation HAT initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize Automation HAT: {e}")
            raise

    def read_door_state(self):
        """Reads the current door state from the reed switch."""
        try:
            switch_state = self._read_switch_state()
            if switch_state is None:
                return None  # Indicate a read failure
            return switch_state == 1
        except Exception as e:
            logging.error(f"Error reading reed switch: {e}")
            return None

    def _read_switch_state(self):
        """Low-level read of the reed switch input."""
        try:
            return int(self.read_gpio(self.reed_pin))
        except Exception as e:
            logging.error(f"Error reading reed switch GPIO: {e}")
            return None

    def read_relay_state(self):
        """Reads the current relay state (on or off)."""
        try:
            return self.relay_device.is_active()
        except Exception as e:
            logging.error(f"Error reading relay state: {e}")
            return None

    def open_door(self):
        """Closes the garage door if it's open, otherwise do nothing."""
        if self.is_door_open:
            logging.info("Opening garage door.")
            self.relay_device.off()
            time.sleep(0.5)  # Allow door to fully close
            self.is_door_open = False
            logging.info("Garage door closed.")

    def close_door(self):
        """Opens the garage door if it's closed, otherwise do nothing."""
        if not self.is_door_open:
            logging.info("Opening garage door.")
            self.relay_device.on()
            time.sleep(0.5)  # Allow door to fully open
            self.is_door_open = True
            logging.info("Garage door closed.")

    def toggle_door(self):
        """Reverses the door state (open to close, close to open)."""
        if self.is_door_open:
            self.close_door()
        else:
            self.open_door()

    def cleanup(self):
        """Releases resources and turns off the relay."""
        logging.info("Cleaning up and turning off relay.")
        if self.relay_device:
            self.relay_device.off()
        if self.relay_device:
            try:
                self.relay_device.cleanup()
            except Exception as e:
                logging.error(f"Error cleaning up relay: {e}")
        logging.info("Cleanup complete.")

    def get_state(self):
        """Returns the current door state (open or closed)."""
        return "open" if self.is_door_open else "closed"


def main():
    """Main function to control the garage door."""
    garage = GarageDoor()

    try:
        while True:
            current_state = garage.get_state()
            logging.info(f"Garage door is: {current_state}")
            choice = input("Open (o) or Close (c)?: ").lower()
            if choice == 'o':
                garage.toggle_door()
            elif choice == 'c':
                garage.close_door()
            else:
                logging.warning("Invalid choice. Use 'o' for open or 'c' for close.")

    except KeyboardInterrupt:
        logging.info("Exiting program due to keyboard interrupt.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        garage.cleanup()


if __name__ == "__main__":
    main()

