import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Configuration constants for the hydroponics controller
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus for the soil moisture sensor."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"I2C initialization failed: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the Adafruit Seesaw soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x48)
    except Exception as e:
        print(f"Sensor initialization failed: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump relay."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pump_pin, GPIO.OUT)
    GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is off initially

def read_moisture(sensor_obj):
    """Read the soil moisture value from the sensor."""
    try:
        return sensor_obj.moisture_read()
    except Exception as e:
        print(f"Sensor read failed: {e}")
        return None

def control_pump(pump_pin, moisture_value, threshold):
    """Control the water pump based on the moisture threshold."""
    if moisture_value is not None:
        if moisture_value < threshold:
            GPIO.output(pump_pin, GPIO.HIGH)
            return "ON"
        else:
            GPIO.output(pump_pin, GPIO.LOW)
            return "OFF"
    return "UNKNOWN"

def main():
    """Main function to run the hydroponics control loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture_level = read_moisture(soil_sensor)
            pump_state = control_pump(PUMP_GPIO_PIN, moisture_level, MOISTURE_THRESHOLD)
            print("Moisture:", moisture_level, "Pump:", pump_state)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting hydroponics controller")
    finally:
        # Ensure the pump is off and resources are released
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        GPIO.cleanup()
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

