import smbus
import time
from datetime import datetime, timezone_utc

# I2C address of the DS1338 RTC
RTC_ADDRESS = 0x68
# Register addresses for the RTC
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
# Register to control the clock
REG_CONTROL = 0x0D


class DS1338:
    """Driver for the Maxim DS1338 RTC over I2C."""

    def __init__(self, bus_number=1, device_address=RTC_ADDRESS):
        """Open the I2C bus and store the device address."""
        try:
            self.bus = smbus.SMBus(bus_number)
        except FileNotFoundError:
            raise IOError("I2C bus not found. Check your Raspberry Pi configuration.")
        self.device_address = device_address

    def __enter__(self):
        """Return the RTC object for the context manager."""
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Close the I2C bus when finished."""
        self.close()

    def close(self):
        """Close the underlying I2C bus."""
        try:
            self.bus.close()
        except Exception as e:  # Catch any I2C close error
            print(f"Error closing RTC bus: {e}")

    def _bcd_to_int(self, bcd):
        """Decode a 2x4bit BCD value to an integer."""
        return int(str(bcd // 16) + str(bcd % 16))

    def _int_to_bcd(self, n):
        """Encode a signed integer to BCD format."""
        tens = n // 10
        units = n % 10
        return (tens * 16) + units

    def _read_register(self, register):
        """Read a single byte from the RTC register."""
        return self.bus.read_byte_data(self.device_address, register)

    def _write_register(self, register, value):
        """Write a single byte to the RTC register."""
        self.bus.write_byte_data(self.device_address, register, value)

    def read_all(self):
        """Read all seven time registers and decode them."""
        try:
            year = self._bcd_to_int(self._read_register(REG_YEAR))
            month = self._bcd_to_int(self._read_register(REG_MONTH))
            date = self._bcd_to_int(self._read_register(REG_DATE))
            day = self._bcd_to_int(self._read_register(REG_DAY))
            hours = self._bcd_to_int(self._read_register(REG_HOURS) & 0x3F) # 24-hour mode
            minutes = self._bcd_to_int(self._read_register(REG_MINUTES))
            seconds = self._bcd_to_int(self._read_register(REG_SECONDS))
            return year, month, date, day, hours, minutes, seconds
        except IOError as e:
            raise IOError(f"Error reading RTC registers: {e}")

    def read_datetime(self):
        """Return the current date and time as a timezone-aware datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            dt = datetime(2000 + year, month, date, hours, minutes, seconds)
            return dt.replace(tzinfo=timezone_utc())
        except IOError as e:
            raise IOError(f"Error reading and parsing datetime: {e}")

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all seven time registers."""
        try:
            self._write_register(REG_SECONDS, self._int_to_bcd(seconds))
            self._write_register(REG_MINUTES, self._int_to_bcd(minutes))
            self._write_register(REG_HOURS, self._int_to_bcd(hours)) # 24-hour mode
            self._write_register(REG_DAY, self._int_to_bcd(day))
            self._write_register(REG_DATE, self._int_to_bcd(date))
            self._write_register(REG_MONTH, self._int_to_bcd(month))
            self._write_register(REG_YEAR, self._int_to_bcd(year % 100)) # years 2000-2099
        except IOError as e:
            raise IOError(f"Error writing to RTC registers: {e}")


    def write_now(self):
        """Write the current time from the RTC."""
        try:
            year, month, date, day, hours, minutes, seconds = self.read_all()
            self.write_all(year, month, date, day, hours, minutes, seconds)
        except IOError as e:
            raise IOError(f"Error writing current time: {e}")

