import serial
import time
import logging
import signal
import sys

# Configure logging for the CO2 sensor reader
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Serial port configuration for the CO2 sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1
# Log file for CO2 concentration readings
LOG_FILE = "co2_readings_log.txt"


def read_co2_concentration(serial_port):
    """Read a line from the serial port and decode it as a CO2 concentration."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return int(line)
        return None
    except ValueError:
        logging.error("Invalid data received from CO2 sensor: %s", line)
        return None
    except Exception as read_error:
        logging.error("Error reading from serial port: %s", read_error)
        return None


def log_reading(co2_ppm, log_file):
    """Append a timestamped CO2 concentration reading to the log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp},{co2_ppm}\n"
    try:
        with open(log_file, "a") as log_handle:
