        return gps_port
    except serial.SerialException as e:
        logging.error("Failed to open GPS port: %s", e)
        return None


def parse_gps_data(raw_line):
    """Parse a raw NMEA line and return a pynmea2 GPGGA object."""
    try:
        nmea_line = pynmea2.parse(raw_line)
        return nmea_line
    except pynmea2.ParseError as e:
        logging.warning("Could not parse NMEA line: %s, error: %s", raw_line, e)
        return None


def extract_coordinates(nmea_line):
    """Extract latitude, longitude, and altitude from a GPGGA sentence."""
    if nmea_line.sentence_type == "GPGGA":
        latitude = nmea_line.latitude
        longitude = nmea_line.longitude
        altitude = nmea_line.altitude
        return latitude, longitude, altitude
    return None, None, None


def log_coordinates(latitude, longitude, altitude):
    """Append a GPS coordinate line to the log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp},{latitude},{longitude},{altitude}\n"
    try:
        with open(log_file_path, "a") as log_file:
            log_file.write(log_entry)
        logging.info("Logged: %s", log_entry.strip())
    except IOError as e:
        logging.error("Failed to write to log file: %s", e)


