    """Main function to read GPS data and log coordinates."""
    gps_port = initialize_gps_port(gps_port, baud_rate, timeout)
    if gps_port is None:
        return

    try:
        while True:
            try:
                line = gps_port.readline().decode("utf-8", errors="ignore").strip()
            except UnicodeDecodeError:
                continue

            nmea_line = parse_gps_data(line)
            if nmea_line:
                latitude, longitude, altitude = extract_coordinates(nmea_line)
                if latitude is not None and longitude is not None:
                    print("Latitude, Longitude: %.6f, %.6f" % (latitude, longitude))
                    log_coordinates(latitude, longitude, altitude)
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Stopping GPS logger")
    finally:
        gps_port.close()


if __name__ == "__main__":
    main()

