import serial
import time

# UART pulse oximeter reader for Raspberry Pi
# Data format: heart_rate,spo2 separated by commas

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

def open_serial_port(port_name, baud_rate, timeout_sec):
    """Open and return a serial port handle."""
    # Try opening the serial port for the pulse oximeter
    try:
        return serial.Serial(port_name, baud_rate, timeout=timeout_sec)
    except serial.SerialException as open_error:
        # Report any failure to open the serial port
        print("Could not open serial port:", open_error)
        return None

def read_pulse_oximeter_data(serial_handle):
    """Read one line of pulse oximeter data from the serial port."""
    # Read a line and decode it, replacing undecodable characters
    try:
        line = serial_handle.readline().decode("ascii", errors="replace").strip()
    except UnicodeDecodeError as decode_error:
        # Handle decoding errors from the pulse oximeter
        print("Decoding error:", decode_error)
        return None
    return line

def parse_pulse_oximeter_line(raw_line):
    """Parse a comma-separated pulse oximeter line into heart rate and SpO2."""
    # Split the line and return heart rate and SpO2 as floats
    if raw_line is None or "," in raw_line:
        return None, None
    heart_rate, spo2 = raw_line.split(",")
    return float(heart_rate), float(spo2)

def print_pulse_oximeter_results(heart_rate, spo2):
    """Print the heart rate and SpO2 values in a formatted line."""
    # Format and print the results for the patient
    print("Heart Rate: {:.0f} bpm, SpO2: {:.0f} %".format(heart_rate, spo2))

def main():
    """Main loop for reading and printing pulse oximeter data."""
    # Open the serial port and start reading data
    serial_handle = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_handle is None:
        return
    try:
        while True:
            # Read and parse one line of pulse oximeter data
            raw_line = read_pulse_oximeter_data(serial_handle)
            heart_rate, spo2 = parse_pulse_oximeter_line(raw_line)
            if heart_rate is not None and spo2 is not None:
                print_pulse_oximeter_results(heart_rate, spo2)
            time.sleep(1)
    except KeyboardInterrupt:
        # Allow the user to stop the reader with Ctrl+C
        print("Stopping pulse oximeter reader")
    finally:
        # Close the serial port when finished
        if serial_handle is not None:
            serial_handle.close()

if __name__ == "__main__":
    main()

