import json
import time
import logging
import threading
import socket
import serial
from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1
DATABASE = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]
APP_PORT = 5000

# Initialize the Flask application
app = Flask(__name__)

# Global variable for serial communication
serial_port = None

# Function to initialize serial communication
def initialize_serial(port=DEFAULT_SERIAL_PORT, baudrate=DEFAULT_BAUDRATE, timeout=DEFAULT_TIMEOUT):
    """
    Initializes the serial port for communication with the instrument.
    """
    global serial_port
    try:
        serial_port = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"Serial port {port} initialized successfully.")
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        raise

# Function to send SCPI command and read response
def send_scpi_command(command):
    """
    Sends an SCPI command to the serial port and returns the response.
    """
    global serial_port
    if serial_port is None:
        logging.error("Serial port not initialized.")
        return None

    try:
        serial_port.write(command.encode())
        time.sleep(0.1)  # Allow time for the instrument to respond
        response = serial_port.readline().decode('utf-8').rstrip()
        return response
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None

# Function to close the serial port
def close_serial():
    """
    Closes the serial port if it's open.
    """
    global serial_port
    if serial_port and serial_port.is_open:
        serial_port.close()
        logging.info("Serial port closed.")

# Decorator for handling HTTP errors
def handle_errors(f):
    """
    Decorator to handle HTTP errors and return error messages.
    """
    def wrapped(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except Exception as e:
            logging.exception("Error occurred in the decorated function:")
            return Response(f"Internal Server Error: {str(e)}", mimetype='text/plain', status=500)
    return wrapped

# Endpoints
@app.route('/version', methods=['GET'])
@handle_errors
def version():
    """
    Returns the version information of the application.
    """
    return Response("Web API for Raspberry Pi Serial Controlled Instruments", mimetype='text/html')

@app.route('/getdata', methods=['GET'])
@handle_errors
def get_data():
    """
    Returns the current data from the database.
    """
    return Response(json.dumps(DATABASE), mimetype='application/json')

@app.route('/getset/<int:item_id>', methods=['GET'])
@handle_errors
def get_item(item_id):
    """
    Returns a specific item from the database.
    """
    item = next((item for item in DATABASE if item['id'] == item_id), None)
    if item:
        return Response(json.dumps(item), mimetype='application/json')
    else:
        return Response("Item not found", status=404, mimetype='text/plain')

@app.route('/getpost/<int:item_id>/<name>', methods=['GET', 'POST'])
@handle_errors
def get_post(item_id, name):
    """
    Handles GET and POST requests for updating an item.
    """
    if request.method == 'GET':
        item = next((item for item in DATABASE if item['id'] == item_id), None)
        if item:
            if request.args.get('name') != None:
                item['name'] = request.args.get('name')
            return Response(json.dumps(item), mimetype='application/json')
        else:
            return Response("Item not found", status=404, mimetype='text/plain')
    elif request.method == 'POST':
        new_item = request.get_json() or {}
        new_item['id'] = DATABASE[-1]['id'] + 1 if DATABASE else 1
        new_item['name'] = new_item.get('name', DATABASE[-1]['name'])
        new_item['done'] = new_item.get('done', DATABASE[-1]['done'])
        DATABASE.append(new_item)
        close_serial()
        return Response(json.dumps(DATABASE), mimetype='application/json')

@app.route('/postjson', methods=['POST'])
@handle_errors
def post_json():
    """
    Handles POST requests with JSON data.
    """
    if request.method == 'POST':
        try:
            data = request.get_json()
            item_id = data.get('id')
            name = data.get('name')
            done = data.get('done')

            if item_id is not None:
                for item in DATABASE:
                    if item['id'] == item_id:
                        item['name'] = name
                        item['done'] = done
                        return Response(json.dumps(DATABASE), mimetype='application/json')
            else:
                new_item = {
                    'id': DATABASE[-1]['id'] + 1 if DATABASE else 1,
                    'name': name,
                    'done': done
                }
                DATABASE.append(new_item)
                close_serial()
                return Response(json.dumps(DATABASE), mimetype='application/json')
        except (KeyError, TypeError) as e:
            logging.exception("Error processing JSON data: %s", e)
            return Response(f"Invalid JSON data: {e}", status=400, mimetype='text/plain')
    else:
        return Response("POST method not allowed", status=405, mimetype='text/plain')

@app.route('/postjson/<int:item_id>', methods=['POST'])
@handle_errors
def post_json_item(item_id):
    """
    Handles POST requests to a specific item.
    """
    if request.method == 'POST':
        try:
            data = request.get_json()
            item = next((item for item in DATABASE if item['id'] == item_id), None)
            if item:
                item.update(data)  # Update existing item
                close_serial()
                return Response(json.dumps(DATABASE), mimetype='application/json')
            else:
                return Response("Item not found", status=404, mimetype='text/plain')
        except (KeyError, TypeError) as e:
            logging.exception("Error processing JSON data: %s", e)
            return Response(f"Invalid JSON data: {e}", status=400, mimetype='text/plain')
    else:
        return Response("POST method not allowed", status=405, mimetype='text/plain')

