        except (KeyError, TypeError) as e:
            logging.exception("Error processing JSON data: %s", e)
            return Response(f"Invalid JSON data: {e}", status=400, mimetype='text/plain')
    else:
        return Response("POST method not allowed", status=405, mimetype='text/plain')

@app.route('/postjson', methods=['POST'])
@handle_errors
def post_json_no_id():
    """
