@app.route('/getset/<int:item_id>', methods=['GET'])
@handle_errors
def get_item(item_id):
    """
    Returns a specific item from the database.
    """
    item = next((item for item in DATABASE if item['id'] == item_id), None)
    if item:
        return Response(json.dumps(item), mimetype='application/json')
    else:
        return Response("Item not found", status=404, mimetype='text/plain')

@app.route('/getpost/<int:item_id>/<name>', methods=['GET', 'POST'])
@handle_errors
def get_post(item_id, name):
    """
    Handles GET and POST requests for updating an item.
    """
    if request.method == 'GET':
        item = next((item for item in DATABASE if item['id'] == item_id), None)
        if item:
            if request.args.get('name') != None:
                item['name'] = request.args.get('name')
            return Response(json.dumps(item), mimetype='application/json')
        else:
            return Response("Item not found", status=404, mimetype='text/plain')
    elif request.method == 'POST':
        new_item = request.get_json() or {}
        new_item['id'] = DATABASE[-1]['id'] + 1 if DATABASE else 1
        new_item['name'] = new_item.get('name', DATABASE[-1]['name'])
        new_item['done'] = new_item.get('done', DATABASE[-1]['done'])
        DATABASE.append(new_item)
        close_serial()
        return Response(json.dumps(DATABASE), mimetype='application/json')

@app.route('/postjson', methods=['POST'])
@handle_errors
def post_json():
    """
    Handles POST requests with JSON data.
    """
    if request.method == 'POST':
        try:
            data = request.get_json()
            item_id = data.get('id')
            name = data.get('name')
            done = data.get('done')

            if item_id is not None:
                for item in DATABASE:
                    if item['id'] == item_id:
                        item['name'] = name
                        item['done'] = done
                        return Response(json.dumps(DATABASE), mimetype='application/json')
            else:
                new_item = {
                    'id': DATABASE[-1]['id'] + 1 if DATABASE else 1,
                    'name': name,
                    'done': done
                }
                DATABASE.append(new_item)
                close_serial()
                return Response(json.dumps(DATABASE), mimetype='application/json')
        except (KeyError, TypeError) as e:
            logging.exception("Error processing JSON data: %s", e)
            return Response(f"Invalid JSON data: {e}", status=400, mimetype='text/plain')
    else:
        return Response("POST method not allowed", status=405, mimetype='text/plain')

